from sage.all_cmdline import *   # import sage library

_sage_const_65537 = Integer(65537); _sage_const_97 = Integer(97); _sage_const_96 = Integer(96); _sage_const_70 = Integer(70); _sage_const_50 = Integer(50); _sage_const_2 = Integer(2); _sage_const_4 = Integer(4); _sage_const_8 = Integer(8); _sage_const_16 = Integer(16); _sage_const_32 = Integer(32); _sage_const_0 = Integer(0); _sage_const_6 = Integer(6); _sage_const_5 = Integer(5); _sage_const_3 = Integer(3); _sage_const_64 = Integer(64); _sage_const_1 = Integer(1)
p = _sage_const_65537 
ell = _sage_const_97 
